```{r, echo=FALSE, warning=FALSE, message=FALSE}
library(htmltools)
library(yaml)

schedule <- yaml::read_yaml("schedule.yml")

format_desc <- function(desc) {
  if (is.null(desc)) return(NULL)

  # Convert bullet list
  lines <- unlist(strsplit(desc, "\n"))

  tags$div(
    class = "event-desc",
    lapply(lines, function(line) {
      line <- trimws(line)

      if (startsWith(line, "- ")) {
        tags$div(paste0("• ", substring(line, 3)))
      } else {
        # tags$div(line)
        tags$div(HTML(line))   # ✅ THIS is the critical fix
      }
    })
  )
}

render_day <- function(day) {
  events <- schedule[[day]]

  div(
    lapply(events, function(e) {

      div(
        class = paste("event-card", e$type),

        div(class = "event-time",
            paste(e$start, "-", e$end)),

        div(class = "event-title", e$name),

        format_desc(e$description)
      )
    })
  )
}
```



